  { auto _e = lod_resolutions(); if (_e) { _o->lod_resolutions.resize(_e->size()); for (::flatbuffers::uoffset_t _i = 0; _i < _e->size(); _i++) { _o->lod_resolutions[_i] = _e->Get(_i); } } else { _o->lod_resolutions.resize(0); } }
